import React from "react";

const Footer = () => {
  return (
    <>
      <style>{`
        .footer {
          background: #0f172a;
          color: #cbd5e1;
          padding: 35px 8%;
          border-top: 1px solid rgba(255,255,255,0.08);
        }

        .footer-container {
          max-width: 1100px;
          margin: auto;
        }

        .footer-header h3 {
          margin: 0;
          font-size: 1.4rem;
          color: #ffffff;
        }

        .footer-header p {
          margin: 6px 0 25px 0;
          font-size: 0.9rem;
          color: #94a3b8;
        }

        .footer-links {
          display: flex;
          gap: 40px;
          flex-wrap: wrap;
          margin-bottom: 30px;
        }

        .footer-links a {
          text-decoration: none;
          color: #cbd5e1;
          font-size: 0.9rem;
          position: relative;
          transition: color 0.3s ease;
        }

        .footer-links a::after {
          content: "";
          position: absolute;
          left: 0;
          bottom: -4px;
          width: 0%;
          height: 1px;
          background: #2563eb;
          transition: width 0.3s ease;
        }

        .footer-links a:hover {
          color: #2563eb;
        }

        .footer-links a:hover::after {
          width: 100%;
        }

        .footer-divider {
          height: 1px;
          background: rgba(255,255,255,0.08);
          margin-bottom: 18px;
        }

        .footer-bottom {
          font-size: 0.75rem;
          color: #64748b;
          text-align: center;
        }

        @media (max-width: 768px) {
          .footer-links {
            gap: 20px;
          }
        }
      `}</style>

      <footer className="footer">
        <div className="footer-container">

          <div className="footer-header">
            <h3>Swetha</h3>
            <p>Crafting scalable digital experiences.</p>
          </div>

          <div className="footer-links">
            <a href="mailto:swethaa1805@email.com">Email</a>
            <a
              href="https://www.linkedin.com/in/swetha-a-0b1712382/"
              target="_blank"
              rel="noopener noreferrer"
            >
              LinkedIn
            </a>
            <a
              href="https://github.com/Swethaa1805"
              target="_blank"
              rel="noopener noreferrer"
            >
              GitHub
            </a>
          </div>

          <div className="footer-divider"></div>

          <div className="footer-bottom">
            © {new Date().getFullYear()} Swetha. All Rights Reserved.
          </div>

        </div>
      </footer>
    </>
  );
};

export default Footer;
